import{_ as t,o as a,c as d,a2 as o}from"./chunks/framework.doxMM-x8.js";const h=JSON.parse('{"title":"开发与验证","description":"","frontmatter":{"docLocale":"zh","counterpart":"/en/testing/feedback-loop","contentType":"guide","prev":false,"next":false},"headers":[],"relativePath":"testing/feedback-loop.md","filePath":"testing/feedback-loop.md"}'),r={name:"testing/feedback-loop.md"};function c(n,e,s,i,l,p){return a(),d("div",null,[...e[0]||(e[0]=[o('<h1 id="开发与验证" tabindex="-1">开发与验证 <a class="header-anchor" href="#开发与验证" aria-label="Permalink to &quot;开发与验证&quot;">​</a></h1><p>目标：为自己的 Lab Word 变更选择能观察结果的公开检查。命令从仓库根目录执行，完整职责见<a href="https://github.com/CaiZongyuan/labworld/blob/240294a75a807367d3bad8fa0b1a14e26ecc1828/docs/testing/strategy.md" target="_blank" rel="noreferrer">测试策略</a>。</p><h2 id="选择入口" tabindex="-1">选择入口 <a class="header-anchor" href="#选择入口" aria-label="Permalink to &quot;选择入口&quot;">​</a></h2><table tabindex="0"><thead><tr><th>变更</th><th>命令</th><th>观察结果与前提</th></tr></thead><tbody><tr><td>Web 行为</td><td><code>pnpm test:frontend</code></td><td>真实组件操作；HTTP 使用 MSW</td></tr><tr><td>TypeScript 与边界</td><td><code>pnpm typecheck</code>、<code>pnpm boundaries:check</code></td><td>类型、包依赖、Rust 表归属</td></tr><tr><td>后端行为</td><td><code>node scripts/test-backend.mjs --test registration</code></td><td>真实 Router 与隔离服务；需要 Docker</td></tr><tr><td>合同</td><td><code>pnpm generate</code>、<code>pnpm contracts:check</code></td><td>Rust/OpenAPI、生成类型与 SDK 一致</td></tr><tr><td>文档</td><td><code>pnpm docs:check</code>、<code>pnpm docs:build</code></td><td>来源、双语、生成参考与实际构建链接</td></tr><tr><td>文档浏览器旅程</td><td><code>just e2e-docs</code></td><td>语言、主题、搜索、窄屏与自定义 base；需 Chromium</td></tr><tr><td>应用关键旅程</td><td><code>just e2e</code></td><td>真实 Web/API/Worker/数据库与存储；需 Docker、Chromium</td></tr></tbody></table><p>首次浏览器验证执行 <code>pnpm exec playwright install chromium</code>。<code>just check</code> 包含主要格式、静态、行为、性能预算与构建检查；它不含浏览器 E2E。<code>just check-full</code> 额外运行应用 E2E。</p><h2 id="lab-viewer-的实际边界" tabindex="-1">Lab Viewer 的实际边界 <a class="header-anchor" href="#lab-viewer-的实际边界" aria-label="Permalink to &quot;Lab Viewer 的实际边界&quot;">​</a></h2><p>已接受的 Viewer 体验由<a href="./../guides/lab-viewer">独立预览</a>保存渲染与资源生命周期证据。本次文档基线的应用测试未覆盖正式 Lab，产品集成需要单独验证。</p><p>正式接入时，组件测试观察导入控件、选择、loading/error 与恢复，浏览器观察真实 GLB/HDR、画布像素、相机和资源释放。DOM 成功不能证明三维模型可见；一次内存采样不能证明泄漏。</p><h2 id="失败与证据" tabindex="-1">失败与证据 <a class="header-anchor" href="#失败与证据" aria-label="Permalink to &quot;失败与证据&quot;">​</a></h2><p>如果 Docker、Chromium 或依赖缺失，记录命令、失败条件和未验证范围，不把跳过视为通过。后端检查使用隔离资源，不清理开发或生产数据。</p><p>在已固定的源码版本和任务范围上记录验证。按照<a href="https://github.com/CaiZongyuan/labworld/blob/240294a75a807367d3bad8fa0b1a14e26ecc1828/docs/agents/development-flow.md" target="_blank" rel="noreferrer">开发流程</a>先做仓库简化，再完成受影响检查与 Standards + Spec review。</p><hr><p>源码版本：<code>240294a75a80</code> · <a href="https://github.com/CaiZongyuan/labworld/blob/240294a75a807367d3bad8fa0b1a14e26ecc1828/docs/testing/t01-feedback-loop.md" target="_blank" rel="noreferrer">本页 Markdown</a></p>',13)])])}const m=t(r,[["render",c]]);export{h as __pageData,m as default};
